-- Entity: proposal (table proposals)

DROP VIEW IF EXISTS learninsurancedb.vw_proposals CASCADE;
CREATE VIEW learninsurancedb.vw_proposals AS
SELECT t.*,
       c.full_name AS customer_name, c.customer_code,
       p.name AS product_name, p.product_code, pt.code AS product_type_code, pt.name AS product_type_name, pt.icon AS product_type_icon,
       a.full_name AS agent_name,
       t.details->'vehicle'->>'vehicleType' AS vehicle_type,
       t.details->'vehicle'->>'registrationNo' AS registration_no
FROM learninsurancedb.proposals t
JOIN learninsurancedb.customers c ON c.id = t.customer_id
JOIN learninsurancedb.insurance_products p ON p.id = t.product_id
JOIN learninsurancedb.insurance_product_types pt ON pt.id = p.product_type_id
LEFT JOIN learninsurancedb.agents a ON a.id = t.agent_id;

-- LIST: search + filters + sort + paging. Returns { items, totalCount, page, pageSize }
DROP FUNCTION IF EXISTS learninsurancedb.fn_proposal_get_all(text, int, int, text, text, jsonb);
CREATE FUNCTION learninsurancedb.fn_proposal_get_all(
    p_search    text  DEFAULT NULL,
    p_page      int   DEFAULT 1,
    p_page_size int   DEFAULT 10,
    p_sort_by   text  DEFAULT NULL,
    p_sort_dir  text  DEFAULT NULL,
    p_filters   jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql STABLE AS $fn$
DECLARE
    v_page   int := GREATEST(COALESCE(p_page, 1), 1);
    v_size   int := LEAST(GREATEST(COALESCE(p_page_size, 10), 1), 500);
    v_sort   text := learninsurancedb.fn_to_snake(p_sort_by);
    v_dir    text := CASE WHEN lower(COALESCE(p_sort_dir, 'DESC')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
    v_where  text := 'WHERE TRUE';
    v_like   text;
    v_key    text;
    v_val    text;
    v_col    text;
    v_total  bigint;
    v_items  jsonb;
BEGIN
    IF v_sort IS NULL OR NOT (v_sort = ANY (ARRAY['id', 'created_date', 'modified_date', 'is_active', 'proposal_no', 'customer_name', 'product_name', 'total_premium', 'sum_insured', 'status', 'submitted_date'])) THEN
        v_sort := 'created_date';
        IF p_sort_by IS NULL THEN v_dir := 'DESC'; END IF;
    END IF;

    IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
        v_like := '%' || btrim(p_search) || '%';
        v_where := v_where || format(' AND (proposal_no::text ILIKE %1$L OR customer_name::text ILIKE %1$L OR customer_code::text ILIKE %1$L OR product_name::text ILIKE %1$L OR registration_no::text ILIKE %1$L)', v_like);
    END IF;

    FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(COALESCE(p_filters, '{}'::jsonb)) LOOP
        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active', 'status', 'product_type_code', 'product_id', 'customer_id', 'agent_id', 'vehicle_type']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

    EXECUTE format('SELECT count(*) FROM learninsurancedb.vw_proposals %s', v_where) INTO v_total;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(learninsurancedb.fn_to_camel(to_jsonb(q))), ''[]''::jsonb)
         FROM (SELECT * FROM learninsurancedb.vw_proposals %s ORDER BY %I %s, id DESC LIMIT %s OFFSET %s) q',
        v_where, v_sort, v_dir, v_size, (v_page - 1) * v_size) INTO v_items;

    RETURN jsonb_build_object('items', v_items, 'totalCount', v_total, 'page', v_page, 'pageSize', v_size);
END
$fn$;

-- GET BY ID: returns the row as JSON, or NULL when not found
CREATE OR REPLACE FUNCTION learninsurancedb.fn_proposal_get_by_id(p_id bigint) RETURNS jsonb
LANGUAGE sql STABLE AS $fn$
    SELECT learninsurancedb.fn_to_camel(to_jsonb(v)) FROM learninsurancedb.vw_proposals v WHERE v.id = p_id;
$fn$;





-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_proposal_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.proposals SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proposal % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_proposal_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_proposal_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM learninsurancedb.fn_proposal_set_active(p_id, FALSE, p_user);
    RETURN jsonb_build_object('id', p_id, 'deleted', TRUE);
END
$fn$;
